// Same three dependent steps: nested callbacks vs a flat promise chain.
const getUser = (id, cb) => setTimeout(() => cb(null, { id, name: 'Ann' }), 5);
const getOrders = (u, cb) => setTimeout(() => cb(null, [u.name + '-o1', u.name + '-o2']), 5);
const getTotal = (o, cb) => setTimeout(() => cb(null, o.length * 10), 5);

// Callback hell: drifts right, repeats the error check each level.
getUser(1, (e1, u) => {
