// Promisified versions give a flat chain with ONE catch.
const p = (fn) => (x) => new Promise((res, rej) => fn(x, (e, v) => (e ? rej(e) : res(v))));
function flat() {
  p(getUser)(1).then(p(getOrders)).then(p(getTotal))
    .then((t) => console.log('flat promise chain total:', t))
    .catch((e) => console.log('err', e));
}

// A promise settles once; later resolve/reject calls are ignored.
let doResolve, doReject;
const p = new Promise((res, rej) => { doResolve = res; doReject = rej; });
console.log('right after creation:', p);          // pending
doResolve('first');
doReject(new Error('ignored'));                    // too late
doResolve('also ignored');
console.log('after settling:', p);                 // fulfilled with 'first'

// "Resolved" is not the same as "settled": locked in, still pending.
const inner = new Promise((res) => setTimeout(() => res('inner done'), 10));
const outer = Promise.resolve(inner);              // same promise returned
const locked = new Promise((res) => res(inner));   // follows inner, still pending
console.log('locked on inner:', locked);

// Handlers always run asynchronously, even on a settled promise.
p.then((v) => console.log('then handler got:', v));
console.log('this line prints BEFORE the then handler');
locked.then((v) => console.log('locked finally:', v, outer === inner));
const bad = Promise.reject(new Error('boom'));
bad.catch((e) => console.log('rejected with:', e.message));

// promisify: turn an error-first callback API into a promise API.
const promisify = (fn) => function (...args) {
  // regular function wrapper keeps "this"; arrow executor can use it
  return new Promise((res, rej) =>
    fn.call(this, ...args, (err, v) => (err ? rej(err) : res(v))));
};

// An error-first callback API that uses "this".
const db = {
  prefix: 'row-',
  read(id, cb) {
    setTimeout(() => (id < 0 ? cb(new Error('bad id')) : cb(null, this.prefix + id)), 5);
  },
};
db.readP = promisify(db.read);   // called as db.readP(...), so this === db

db.readP(7).then((v) => console.log('ok:', v));
db.readP(-1).catch((e) => console.log('error:', e.message));

// A buggy double callback is harmless: the promise settles once.
const twice = promisify((x, cb) => { cb(null, x); cb(null, x + 1); cb(new Error('late')); });
twice(1).then((v) => console.log('double callback result:', v));

// What does .then return, and how does the new promise get its value?
const show = (label) => (v) => console.log(label, '->', v);
const p = Promise.resolve(1);

p.then((v) => v + 1).then(show('plain value'));                    // 2
p.then((v) => Promise.resolve(v + 10)).then(show('adopted promise')); // 11
p.then(() => { throw new Error('oops'); })
  .then(show('skipped'))                                           // skipped
  .catch((e) => console.log('throw rejects ->', e.message));
p.then(() => {}).then(show('no return'));                          // undefined

// Missing handler: value or error passes through unchanged.
p.then(null).then(show('pass-through value'));                     // 1
Promise.reject(new Error('e1'))
  .then(show('success handler skipped'))
  .catch((e) => 'recovered from ' + e.message)                    // returns normally
  .then(show('after catch'));

// finally gets no argument and passes the result through.
p.finally((arg) => console.log('finally arg:', arg)).then(show('after finally'));
console.log('start: all handlers above run later');

// all, allSettled, race, any on the same inputs.
const ok = (v, ms) => new Promise((r) => setTimeout(() => r(v), ms));
const bad = (m, ms) => new Promise((_, j) => setTimeout(() => j(new Error(m)), ms));

async function main() {
  console.log('all ok  :', await Promise.all([ok('A', 20), ok('B', 5)])); // input order
  try { await Promise.all([ok('A', 20), bad('x', 5)]); }
  catch (e) { console.log('all fail:', e.message); }                      // first rejection

  const s = await Promise.allSettled([ok('A', 5), bad('x', 5)]);
  console.log('allSettled:', JSON.stringify(s.map((r) => [r.status, r.value || r.reason.message])));

  console.log('race    :', await Promise.race([ok('slow', 20), ok('fast', 5)]));
  try { await Promise.race([bad('quick fail', 5), ok('slow ok', 20)]); }
  catch (e) { console.log('race err:', e.message); }                     // first to settle

  console.log('any     :', await Promise.any([bad('x', 5), ok('good', 15)]));
  try { await Promise.any([bad('e1', 5), bad('e2', 6)]); }
  catch (e) { console.log('any err :', e.constructor.name, e.errors.map((x) => x.message)); }

  console.log('all([]) :', await Promise.all([]));                        // []
  try { await Promise.any([]); } catch (e) { console.log('any([]) :', e.constructor.name); }
}
main();

// A rejection skips success handlers until a rejection handler is found.
const log = (m) => console.log(m);
Promise.resolve('start')
  .then((v) => { log('step 1 ok: ' + v); throw new Error('fail in step 1'); })
  .then(() => log('step 2 (skipped)'))
  .then(() => log('step 3 (skipped)'))
  .catch((e) => { log('caught: ' + e.message); return 'recovered'; }) // returns normally
  .then((v) => { log('chain continues with: ' + v); throw new Error('second error'); })
  .catch((e) => { log('caught again: ' + e.message); throw e; })     // rethrow keeps it rejected
  .then(() => log('skipped because rethrown'))
  .catch((e) => log('final catch: ' + e.message));

// Floating promise: not returned, so the outer chain cannot see its error.
Promise.resolve().then(() => {
  Promise.reject(new Error('floating')).catch((e) => log('handled separately: ' + e.message));
  return 'outer chain finished fine';
}).then(log);

// An error thrown inside a plain setTimeout callback never reaches a promise.
new Promise((res) => setTimeout(() => res('promise fine'), 5)).then(log);

// Sequential vs parallel: same three tasks, different total time.
const task = (name, ms) => () => new Promise((res) => {
  setTimeout(() => { console.log('  finished', name); res(name); }, ms);
});
const tasks = [task('A', 30), task('B', 10), task('C', 20)];

async function main() {
  let t = Date.now();
  console.log('parallel (start all at once):');
  console.log('  results:', await Promise.all(tasks.map((f) => f())));   // ~max = 30 ms
  const par = Date.now() - t;

  t = Date.now();
  console.log('sequential (one after another):');
  const out = [];
  for (const f of tasks) out.push(await f());                            // ~sum = 60 ms
  console.log('  results:', out);
  const seq = Date.now() - t;
  console.log('  parallel (~30 ms) faster than sequential (~60 ms):', par < seq);

  console.log('reduce version:');
  const last = await tasks.reduce((p, f) => p.then(f), Promise.resolve());
  console.log('  last result:', last);
}
main();

