// Timeout wrapper: race against a timer, clean up, and abort the real work.
class TimeoutError extends Error {}

function withTimeout(p, ms) {
  let id;
  const timer = new Promise((_, rej) => { id = setTimeout(() => rej(new TimeoutError('timed out after ' + ms + ' ms')), ms); });
  return Promise.race([p, timer]).finally(() => clearTimeout(id)); // clear on both outcomes
}

const sleep = (ms, v, signal) => new Promise((res, rej) => {
  const id = setTimeout(() => res(v), ms);
  if (signal) signal.addEventListener('abort', () => { clearTimeout(id); rej(signal.reason); });
});

async function main() {
  console.log('fast:', await withTimeout(sleep(10, 'done in time'), 100));
  try { await withTimeout(sleep(100, 'too slow'), 20); }
  catch (e) { console.log('slow:', e.constructor.name, '-', e.message); }

  // race does not cancel the work; a signal does.
  try { await sleep(100, 'x', AbortSignal.timeout(20)); }
  catch (e) { console.log('signal timeout:', e.name); }
  // Combine a user cancel with a timeout.
  const user = new AbortController();
  setTimeout(() => user.abort(new Error('user cancelled')), 5);
  try { await sleep(100, 'x', AbortSignal.any([user.signal, AbortSignal.timeout(50)])); }
  catch (e) { console.log('combined:', e.message); }
}
main();

// Retry with exponential backoff and jitter.
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function retry(fn, { retries = 3, baseDelay = 10, maxDelay = 100, retryable = () => true } = {}) {
  let last;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try { return await fn(attempt); }
    catch (err) {
      last = err;
      if (attempt === retries || !retryable(err)) break;   // out of tries or not retryable
      const cap = Math.min(maxDelay, baseDelay * 2 ** attempt); // 10, 20, 40, ...
      const wait = Math.random() * cap;                    // "full jitter" avoids herds
      console.log('  attempt', attempt + 1, 'failed (' + err.message + '), cap', cap, 'ms');
      await sleep(wait);
    }
  }
  throw last;
}

async function main() {
  const flaky = async (n) => { if (n < 2) throw new Error('503'); return 'ok on attempt ' + (n + 1); };
  console.log('result:', await retry(flaky));
  const notRetry = async () => { const e = new Error('400 bad input'); e.status = 400; throw e; };
  try { await retry(notRetry, { retryable: (e) => e.status !== 400 }); }
  catch (e) { console.log('gave up immediately:', e.message); }
  try { await retry(async () => { throw new Error('503'); }, { retries: 2 }); }
  catch (e) { console.log('exhausted, last error:', e.message); }
}
main();

// Unbounded Promise.all vs a small pool: track peak concurrency.
let running = 0, peak = 0;
const work = async (i) => {
  running++; peak = Math.max(peak, running);
  await new Promise((r) => setTimeout(r, 5));
  running--;
  return i * 2;
};

async function mapLimit(items, limit, fn) {
  const results = new Array(items.length);
  let next = 0;
  async function worker() {
    while (next < items.length) {            // each worker pulls the next index
      const i = next++;
      results[i] = await fn(items[i]);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return results;
}

async function main() {
  const items = Array.from({ length: 20 }, (_, i) => i);
  await Promise.all(items.map(work));
  console.log('Promise.all peak concurrency:', peak);
  running = 0; peak = 0;
  const out = await mapLimit(items, 4, work);
  console.log('mapLimit(4) peak concurrency:', peak);
  console.log('results in order:', out.slice(0, 6).join(','), '...');
}
main();

// Cancellation with AbortController: the task cooperates with a signal.
function download(name, ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal.aborted) return reject(signal.reason);        // already cancelled
    const id = setTimeout(() => { signal.removeEventListener('abort', onAbort); resolve(name + ' done'); }, ms);
    function onAbort() {
      clearTimeout(id);                                      // clean up the real work
      reject(signal.reason);                                 // reject with the abort reason
    }
    signal.addEventListener('abort', onAbort, { once: true });
  });
}

async function main() {
  const c1 = new AbortController();
  console.log(await download('file1', 10, c1.signal));

  const c2 = new AbortController();
  const p = download('file2', 100, c2.signal);
  setTimeout(() => c2.abort(), 10);                          // user cancels
  try { await p; } catch (e) { console.log('file2:', e.name, '-', e.message); }

  try { await download('file3', 100, AbortSignal.timeout(10)); }
  catch (e) { console.log('file3:', e.name); }

  // A shared signal cancels many tasks at once.
  const c3 = new AbortController();
  const all = Promise.allSettled([1, 2, 3].map((i) => download('part' + i, 100, c3.signal)));
  c3.abort(new Error('stop everything'));
  console.log((await all).map((r) => r.status + ':' + r.reason.message).join(' | '));
}
main();
